		goto end;

	p11->C_Login(session, login_type, (CK_UTF8CHAR *) pin, strlen(pin));
	p11->C_CreateObject(session, data_templ, n_data_attr, &data_obj);
	p11->C_CloseSession(session);
	p11->C_Finalize(NULL);
end:
	free(data_templ);
	free(pin);
}

